-- ============================================
-- LUMA — Thème 11 : LONG 3/3 x4 — Un incident à gérer en tant que spectateur impliqué
-- ============================================


update scenarios set content = '{"characters": {"stranger": "l''inconnu en détresse", "security": "la sécurité", "medic": "le secouriste", "security_lead": "le chef de la sécurité"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(The crowd surges forward suddenly as the headliner takes the stage, pressure building around you.)", "text_fr": "(La foule surgit soudainement en avant alors que le concert principal commence, la pression s''accumulant autour de vous.)", "choices": [{"text": "(Stay calm and try to create space around yourself.)", "text_fr": "(Reste calme et essaie de créer de l''espace autour de toi.)", "next": "n2"}, {"text": "(Look around for the nearest safe exit point.)", "text_fr": "(Cherche autour de toi le point de sortie sûr le plus proche.)", "next": "n2b"}]}, "n2": {"speaker": "you_thought", "text": "(You notice someone nearby struggling to stay upright, looking increasingly panicked.)", "text_fr": "(Vous remarquez quelqu''un à proximité qui a du mal à rester debout, semblant de plus en plus paniqué.)", "choices": [{"text": "Reach out to steady them and check if they''re okay.", "text_fr": "Tends la main pour les stabiliser et vérifie s''ils vont bien.", "next": "n3"}]}, "n2b": {"speaker": "you_thought", "text": "(You spot an exit path but notice others seem unaware of the growing danger.)", "text_fr": "(Vous repérez un chemin de sortie mais remarquez que d''autres semblent inconscients du danger grandissant.)", "choices": [{"text": "Warn people nearby about the pressure building up ahead.", "text_fr": "Avertis les gens à proximité de la pression qui s''accumule devant.", "next": "n3"}]}, "n3": {"speaker": "stranger", "text": "(Gasping) I can''t... breathe properly, too many people pressing in...", "text_fr": "(Haletant) Je peux... plus bien respirer, trop de gens qui pressent...", "choices": [{"text": "Stay with me, let''s move sideways together, away from the center.", "text_fr": "Reste avec moi, bougeons sur le côté ensemble, loin du centre.", "next": "n4"}, {"text": "(Signal loudly for security to help clear space in this area.)", "text_fr": "(Fais signe bruyamment à la sécurité pour dégager de l''espace dans cette zone.)", "next": "n4"}]}, "n4": {"speaker": "you_thought", "text": "(Working together, you both slowly push sideways through the crowd toward more open space.)", "text_fr": "(Travaillant ensemble, vous poussez tous les deux lentement sur le côté à travers la foule vers plus d''espace ouvert.)", "choices": [{"text": "(Keep encouraging them as you both make progress.)", "text_fr": "(Continue à les encourager pendant que vous progressez tous les deux.)", "next": "n5"}]}, "n5": {"speaker": "security", "text": "(Arrives, radio in hand) We''re clearing this section now, thank you for the warning!", "text_fr": "(Arrive, radio en main) On dégage cette section maintenant, merci pour l''avertissement !", "choices": [{"text": "This person needs help, they were struggling to breathe.", "text_fr": "Cette personne a besoin d''aide, elle avait du mal à respirer.", "next": "n6"}]}, "n6": {"speaker": "security", "text": "(Checks the stranger) Let''s get you to the medical tent just to be safe.", "text_fr": "(Vérifie l''inconnu) Allons vous amener à la tente médicale juste pour être sûr.", "choices": [{"text": "I''ll come with you both, just to make sure everything''s okay.", "text_fr": "Je viens avec vous deux, juste pour m''assurer que tout va bien.", "next": "n7"}, {"text": "I''ll stay here to help guide others away from the crowded area.", "text_fr": "Je vais rester ici pour aider à guider les autres loin de la zone bondée.", "next": "n7b"}]}, "n7": {"speaker": "stranger", "text": "(Breathing easier now) Thank you... I don''t know what would''ve happened without your help.", "text_fr": "(Respirant plus facilement maintenant) Merci... je sais pas ce qui se serait passé sans votre aide.", "choices": [{"text": "I''m just glad we got you to safety in time.", "text_fr": "Je suis juste content qu''on t''ait mis en sécurité à temps.", "next": "n8"}]}, "n7b": {"speaker": "you_thought", "text": "(You spend the next several minutes helping redirect the crowd flow safely.)", "text_fr": "(Vous passez les minutes suivantes à aider à rediriger le flux de la foule en toute sécurité.)", "choices": [{"text": "(Continue helping until the area feels properly under control.)", "text_fr": "(Continue à aider jusqu''à ce que la zone semble bien sous contrôle.)", "next": "n8"}]}, "n8": {"speaker": "medic", "text": "(At the medical tent) Vitals look good, just needed some space and water. You did the right thing.", "text_fr": "(À la tente médicale) Les signes vitaux ont l''air bons, il avait juste besoin d''espace et d''eau. Vous avez bien fait.", "choices": [{"text": "I''m relieved to hear that. Crowd crushes can be really scary.", "text_fr": "Je suis soulagé d''entendre ça. Les mouvements de foule peuvent être vraiment effrayants.", "next": "n9"}]}, "n9": {"speaker": "security_lead", "text": "We really appreciate festival-goers like you who stay alert and help others. Thank you.", "text_fr": "On apprécie vraiment les festivaliers comme vous qui restent alertes et aident les autres. Merci.", "choices": [{"text": "Of course, I just did what anyone should do in that situation.", "text_fr": "Bien sûr, j''ai juste fait ce que tout le monde devrait faire dans cette situation.", "next": "n10"}]}, "n10": {"speaker": "stranger", "text": "(Recovered, smiling) Hey, want to watch the rest of the show together, from somewhere safer this time?", "text_fr": "(Rétabli, souriant) Hé, tu veux regarder le reste du spectacle ensemble, depuis un endroit plus sûr cette fois ?", "choices": [{"text": "I''d like that a lot, actually. Let''s find a good spot.", "text_fr": "J''aimerais beaucoup ça, en fait. Trouvons un bon endroit.", "next": "end_helped"}]}, "end_helped": {"speaker": "stranger", "text": "Funny how a scary moment turned into meeting someone genuinely kind. Thank you again.", "text_fr": "C''est marrant comment un moment effrayant s''est transformé en rencontre avec quelqu''un de vraiment gentil. Merci encore.", "end": true, "ending_label": "Incident géré avec calme, une vie peut-être sauvée 🚨🙏"}}}'::jsonb, is_playable = true
where title = 'Un incident à gérer en tant que spectateur impliqué'
  and theme_id = (select id from scenario_themes where position = 11 and language_id = (select id from languages where code = 'en'));
